python3 -c "
import json, glob, os
os.chdir('/root/acr-vla-conformal-refinement')
print('=== PROCESSES ===')
for pid_dir in os.listdir('/proc'):
    if pid_dir.isdigit():
        try:
            cmdline = open(f'/proc/{pid_dir}/cmdline').read()
            if 'evaluate.py' in cmdline:
                print(f'PID={pid_dir} CMD={cmdline.replace(chr(0), chr(32))}')
        except:
            pass
print('=== LOGS ===')
for f in sorted(glob.glob('logs/eval_*.json')):
    try:
        d = json.load(open(f))
        tasks = d.get('task_results', d.get('results', {}))
        n = len(tasks)
        if isinstance(tasks, dict):
            srs = [v.get('success_rate', v.get('sr', -1)) for v in tasks.values() if isinstance(v, dict)]
            valid = [s for s in srs if not s < 0]
            avg_sr = sum(valid) / max(len(valid), 1)
            print(f'{os.path.basename(f)}: {n}/10, avg_sr={avg_sr:.1f}%')
            for k, v in tasks.items():
                sr = v.get('success_rate', v.get('sr', 'N/A')) if isinstance(v, dict) else v
                print(f'  {k}: {sr}')
        else:
            print(f'{os.path.basename(f)}: {n}/10')
    except Exception as e:
        print(f'{os.path.basename(f)}: ERR {e}')
"

